VALUES ('gr20', 'GR 20 — Traversée de la Corse', 'GR 20', 'Corse', '#ef4444', 180, 12000, 16, 'Le sentier de grande randonnée le plus dur d''Europe. Traversée nord-sud de la Corse par les crêtes granitiques, de Calenzana à Conca.', '[{"name":"Calenzana","lat":42.508,"lng":8.855,"ele":275},{"name":"Refuge d'Ortu di u Piobbu","lat":42.456,"lng":8.904,"ele":1570},{"name":"Refuge de Carrozzu","lat":42.418,"lng":8.922,"ele":1270},{"name":"Haut Asco","lat":42.404,"lng":8.922,"ele":1422},{"name":"Refuge de Tighjettu","lat":42.378,"lng":8.895,"ele":1683},{"name":"Ciottulu di i Mori","lat":42.349,"lng":8.88,"ele":1991},{"name":"Castel de Vergio","lat":42.306,"lng":8.945,"ele":1404},{"name":"Refuge de Manganu","lat":42.274,"lng":8.957,"ele":1601},{"name":"Refuge de Petra Piana","lat":42.225,"lng":9.033,"ele":1842},{"name":"Refuge de l'Onda","lat":42.174,"lng":9.074,"ele":1430},{"name":"Vizzavona","lat":42.128,"lng":9.132,"ele":920},{"name":"Bergeries de Capanelle","lat":42.072,"lng":9.175,"ele":1586},{"name":"Refuge de Prati","lat":42.013,"lng":9.176,"ele":1820},{"name":"Refuge de Usciolu","lat":41.932,"lng":9.173,"ele":1750},{"name":"Refuge d'Asinau","lat":41.853,"lng":9.2,"ele":1536},{"name":"Refuge de Paliri","lat":41.778,"lng":9.261,"ele":1055},{"name":"Conca","lat":41.735,"lng":9.333,"ele":252}]'::jsonb, '[{"number":1,"name":"Calenzana ➔ Ortu di u Piobbu","distanceKm":12,"dPlus":1500,"dMinus":200,"timeEst":"7h00"},{"number":2,"name":"Ortu di u Piobbu ➔ Carrozzu","distanceKm":7,"dPlus":700,"dMinus":1000,"timeEst":"6h00"},{"number":3,"name":"Carrozzu ➔ Haut Asco (Passerelle de Spasimata)","distanceKm":6,"dPlus":800,"dMinus":650,"timeEst":"5h30"},{"number":4,"name":"Haut Asco ➔ Tighjettu (Cirque de la Solitude)","distanceKm":8,"dPlus":1200,"dMinus":940,"timeEst":"8h00"},{"number":5,"name":"Tighjettu ➔ Ciottulu di i Mori","distanceKm":5,"dPlus":600,"dMinus":300,"timeEst":"4h00"},{"number":6,"name":"Ciottulu ➔ Castel de Vergio","distanceKm":15,"dPlus":400,"dMinus":990,"timeEst":"5h30"},{"number":7,"name":"Castel de Vergio ➔ Manganu (Lac de Nino)","distanceKm":15,"dPlus":700,"dMinus":500,"timeEst":"6h30"},{"number":8,"name":"Manganu ➔ Petra Piana (Brèche de Capitello)","distanceKm":9,"dPlus":850,"dMinus":600,"timeEst":"6h00"},{"number":9,"name":"Petra Piana ➔ l'Onda","distanceKm":10,"dPlus":500,"dMinus":900,"timeEst":"5h30"},{"number":10,"name":"L'Onda ➔ Vizzavona (Monte d'Oro)","distanceKm":10,"dPlus":700,"dMinus":1200,"timeEst":"6h30"},{"number":11,"name":"Vizzavona ➔ Capanelle","distanceKm":14,"dPlus":900,"dMinus":250,"timeEst":"5h00"},{"number":12,"name":"Capanelle ➔ Prati (Plateau du Coscione)","distanceKm":15,"dPlus":850,"dMinus":620,"timeEst":"6h00"},{"number":13,"name":"Prati ➔ Usciolu","distanceKm":10,"dPlus":700,"dMinus":780,"timeEst":"5h30"},{"number":14,"name":"Usciolu ➔ Asinau (Arête des Statues)","distanceKm":13,"dPlus":750,"dMinus":960,"timeEst":"7h00"},{"number":15,"name":"Asinau ➔ Paliri (Aiguilles de Bavella)","distanceKm":12,"dPlus":450,"dMinus":930,"timeEst":"6h00"},{"number":16,"name":"Paliri ➔ Conca","distanceKm":12,"dPlus":160,"dMinus":960,"timeEst":"5h00"}]'::jsonb);

INSERT INTO public.gr_routes (id, name, short_name, region, color, distance_km, elevation_gain_m, recommended_days, description, waypoints, stages) 
VALUES ('tmb', 'Tour du Mont-Blanc', 'TMB', 'Alpes — France / Italie / Suisse', '#3b82f6', 170, 10000, 10, 'Le tour du massif du Mont-Blanc à travers 3 pays. Glaciers, cols alpins, vallées verdoyantes. L''un des plus beaux treks d''Europe.', '[{"name":"Les Houches","lat":45.891,"lng":6.798,"ele":1008},{"name":"Les Contamines-Montjoie","lat":45.823,"lng":6.726,"ele":1164},{"name":"Les Chapieux","lat":45.696,"lng":6.734,"ele":1549},{"name":"Courmayeur","lat":45.797,"lng":6.968,"ele":1224},{"name":"Refuge Bonatti","lat":45.845,"lng":7.032,"ele":2025},{"name":"La Fouly","lat":45.933,"lng":7.098,"ele":1593},{"name":"Champex-Lac","lat":46.028,"lng":7.115,"ele":1466},{"name":"Trient","lat":46.056,"lng":6.994,"ele":1297},{"name":"Tré-le-Champ","lat":45.989,"lng":6.934,"ele":1417},{"name":"La Flégère","lat":45.961,"lng":6.886,"ele":1877},{"name":"Les Houches","lat":45.891,"lng":6.798,"ele":1008}]'::jsonb, '[{"number":1,"name":"Les Houches ➔ Les Contamines","distanceKm":16,"dPlus":650,"dMinus":640,"timeEst":"5h30"},{"number":2,"name":"Les Contamines ➔ Les Chapieux (Col du Bonhomme 2329m)","distanceKm":18,"dPlus":1300,"dMinus":930,"timeEst":"7h30"},{"number":3,"name":"Les Chapieux ➔ Courmayeur (Col de la Seigne 2516m)","distanceKm":25,"dPlus":1000,"dMinus":1320,"timeEst":"8h30"},{"number":4,"name":"Courmayeur ➔ Refuge Bonatti","distanceKm":12,"dPlus":860,"dMinus":60,"timeEst":"4h30"},{"number":5,"name":"Refuge Bonatti ➔ La Fouly (Grand Col Ferret 2537m)","distanceKm":20,"dPlus":890,"dMinus":1310,"timeEst":"7h00"},{"number":6,"name":"La Fouly ➔ Champex-Lac","distanceKm":15,"dPlus":420,"dMinus":560,"timeEst":"4h30"},{"number":7,"name":"Champex-Lac ➔ Trient (Fenêtre d'Arpette 2665m)","distanceKm":16,"dPlus":1200,"dMinus":1370,"timeEst":"7h00"},{"number":8,"name":"Trient ➔ Tré-le-Champ (Col de Balme 2191m)","distanceKm":15,"dPlus":900,"dMinus":780,"timeEst":"5h30"},{"number":9,"name":"Tré-le-Champ ➔ La Flégère (Lac Blanc)","distanceKm":15,"dPlus":1080,"dMinus":620,"timeEst":"6h00"