VALUES ('gr34', 'GR 34 — Sentier des Douaniers (Bretagne)', 'GR 34', 'Bretagne — Tour de la côte', '#0ea5e9', 2090, 16700, 120, 'Le plus long GR de France. Tour complet de la côte bretonne du Mont-Saint-Michel au pont de Saint-Nazaire. Falaises, plages, ports, phares et landes.', '[{"name":"Mont-Saint-Michel","lat":48.636,"lng":-1.512,"ele":10},{"name":"Cancale","lat":48.671,"lng":-1.851,"ele":30},{"name":"Saint-Malo","lat":48.649,"lng":-2.007,"ele":15},{"name":"Cap Fréhel","lat":48.684,"lng":-2.319,"ele":70},{"name":"Saint-Brieuc","lat":48.514,"lng":-2.76,"ele":50},{"name":"Paimpol","lat":48.777,"lng":-3.046,"ele":20},{"name":"Perros-Guirec (Côte de Granit Rose)","lat":48.815,"lng":-3.444,"ele":25},{"name":"Morlaix","lat":48.577,"lng":-3.828,"ele":10},{"name":"Roscoff","lat":48.726,"lng":-3.981,"ele":5},{"name":"Brest","lat":48.391,"lng":-4.486,"ele":35},{"name":"Presqu'île de Crozon (Camaret)","lat":48.275,"lng":-4.593,"ele":30},{"name":"Douarnenez","lat":48.094,"lng":-4.33,"ele":15},{"name":"Pointe du Raz","lat":48.037,"lng":-4.734,"ele":72},{"name":"Audierne","lat":48.024,"lng":-4.541,"ele":10},{"name":"Quimper","lat":47.998,"lng":-4.099,"ele":10},{"name":"Concarneau","lat":47.875,"lng":-3.919,"ele":15},{"name":"Lorient","lat":47.747,"lng":-3.366,"ele":10},{"name":"Quiberon","lat":47.483,"lng":-3.121,"ele":10},{"name":"Vannes","lat":47.659,"lng":-2.761,"ele":10},{"name":"La Roche-Bernard","lat":47.52,"lng":-2.304,"ele":20},{"name":"Saint-Nazaire","lat":47.274,"lng":-2.213,"ele":10}]'::jsonb, '[{"number":1,"name":"Tronçon Côte d'Émeraude (Mont-St-Michel ➔ St-Malo ➔ Cap Fréhel)","distanceKm":120,"dPlus":1200,"dMinus":1200,"timeEst":"7 jours"},{"number":2,"name":"Tronçon Côtes d'Armor (Cap Fréhel ➔ Paimpol ➔ Perros-Guirec)","distanceKm":200,"dPlus":1800,"dMinus":1800,"timeEst":"11 jours"},{"number":3,"name":"Tronçon Côte de Granit Rose & Trégor (Perros-Guirec ➔ Morlaix)","distanceKm":120,"dPlus":1100,"dMinus":1100,"timeEst":"7 jours"},{"number":4,"name":"Tronçon Finistère Nord (Morlaix ➔ Brest)","distanceKm":200,"dPlus":1600,"dMinus":1600,"timeEst":"11 jours"},{"number":5,"name":"Tronçon Presqu'île de Crozon & Pointe du Raz (Brest ➔ Audierne)","distanceKm":250,"dPlus":2400,"dMinus":2400,"timeEst":"14 jours"},{"number":6,"name":"Tronçon Cornouaille (Audierne ➔ Concarneau ➔ Lorient)","distanceKm":280,"dPlus":2200,"dMinus":2200,"timeEst":"15 jours"},{"number":7,"name":"Tronçon Morbihan (Lorient ➔ Quiberon ➔ Vannes ➔ St-Nazaire)","distanceKm":350,"dPlus":2000,"dMinus":2000,"timeEst":"19 jours"}]'::jsonb);

